import Foundation
import Testing
@testable import DiscordVoiceCodecs

@Suite("CELT recursive mono/stereo shape syntax")
struct CELTShapeCodingTests {
    /// Independent scalar libopus contexts and outputs, never generated by the test subject.
    private struct Fixture: Decodable {
        let input: Input; let output: Output
        struct Input: Decodable {
            let band: Int; let lm: Int; let c: Int; let transient: Bool; let tf: Int; let spread: Int
            let intensity: Int; let disable: Bool; let avoid: Bool; let round: Int; let bytes: Int; let b: Int
            let remaining: Int; let seed: UInt32; let fill: UInt8; let energy: [Float]; let x: [Float]; let low: [Float]?
        }
        struct Output: Decodable {
            let coefficients: [Float]; let folding: [Float]; let mask: UInt8; let remaining: Int; let seed: UInt32
            let range: UInt32; let bits: Int; let fraction: Int
            let decoded: [Float]; let decodedFolding: [Float]; let decodedMask: UInt8; let decodedRemaining: Int
            let decodedSeed: UInt32; let decodedRange: UInt32; let decodedBits: Int; let decodedFraction: Int; let bytes: [UInt8]
        }
    }

    /// Exact independent bytes, final ranges, whole/fractional bits, masks, noise seed and
    /// remaining authority cover recursive partitions, scalar/N2 stereo, angle policies,
    /// intensity/inversion, pulse reduction, zero/folded/noise bands and every TF table output.
    /// Reconstruction is checked within scalar-float tolerance; this is no PCM conformance claim.
    @Test func officialRecursiveShapeOracle() throws {
        let fixtures = try JSONDecoder().decode([Fixture].self, from: Data(CELTShapeOracleFixtures.json.utf8))
        #expect(fixtures.count == 50)
        var splits = 0
        for fixture in fixtures {
            let x = fixture.input, e = fixture.output
            let q = try CELTShapeCoding(frameSampleCount: 120 << x.lm, bandIndex: x.band,
                channelCount: x.c, transient: x.transient, timeFrequencyChange: x.tf,
                spreading: try #require(CELTSpreading(rawValue: x.spread)), intensityBand: x.intensity,
                disableInversion: x.disable, avoidSplitNoise: x.avoid, thetaRounding: x.round)
            #expect(q.dimensions == (CELTAllocationTables.bandEdges[x.band + 1] - CELTAllocationTables.bandEdges[x.band]) << x.lm)
            #expect(q.frameSampleCount == 120 << x.lm && q.bandIndex == x.band && q.channelCount == x.c)
            #expect(q.transient == x.transient && q.timeFrequencyChange == x.tf && q.spreading.rawValue == x.spread)
            #expect(q.intensityBand == x.intensity && q.disableInversion == x.disable)
            #expect(q.avoidSplitNoise == x.avoid && q.thetaRounding == x.round)
            var encoder = try OpusRangeEncoder(frameByteCount: x.bytes)
            let v = try q.encode(x.x, allocationEighthBits: x.b, remainingEighthBits: x.remaining,
                seed: x.seed, folding: x.low, fillMask: x.fill, bandEnergies: Array(x.energy.prefix(x.c)), into: &encoder)
            assertFloats(v.coefficients, e.coefficients); assertFloats(v.folding, e.folding)
            #expect(v.collapseMask == e.mask && v.remainingEighthBits == e.remaining && v.seed == e.seed)
            #expect(encoder.finalRange == e.range && encoder.bitsUsed == e.bits && encoder.fractionalBitsUsed == e.fraction)
            #expect(Array(try encoder.finalize()) == e.bytes)
            var decoder = try OpusRangeDecoder(frame: Data(e.bytes))
            let d = try q.decode(allocationEighthBits: x.b, remainingEighthBits: x.remaining,
                seed: x.seed, folding: x.low, fillMask: x.fill, from: &decoder)
            assertFloats(d.coefficients, e.decoded); assertFloats(d.folding, e.decodedFolding)
            #expect(d.collapseMask == e.decodedMask && d.remainingEighthBits == e.decodedRemaining && d.seed == e.decodedSeed)
            #expect(decoder.finalRange == e.decodedRange && decoder.bitsUsed == e.decodedBits && decoder.fractionalBitsUsed == e.decodedFraction)
            #expect(v.recursiveSplits == d.recursiveSplits)
            splits += v.recursiveSplits
        }
        #expect(splits > 0)
    }

    /// Rejects invalid scalar contexts, including extreme integers before any shift/table access.
    @Test func invalidConfiguration() throws {
        for samples in [Int.min, -1, 0, 119, 121, 1920, Int.max] {
            #expect(throws: CELTShapeCodingError.invalidFrameSize) { try CELTShapeCoding(frameSampleCount: samples, bandIndex: 0) }
        }
        for band in [Int.min, -1, 21, Int.max] {
            #expect(throws: CELTShapeCodingError.invalidBandIndex) { try CELTShapeCoding(frameSampleCount: 120, bandIndex: band) }
        }
        for channels in [Int.min, 0, 3, Int.max] {
            #expect(throws: CELTShapeCodingError.invalidChannelCount) { try CELTShapeCoding(frameSampleCount: 120, bandIndex: 0, channelCount: channels) }
        }
        for tf in [Int.min, -4, 1, 4, Int.max] {
            #expect(throws: CELTShapeCodingError.invalidTimeFrequencyChange) { try CELTShapeCoding(frameSampleCount: 120, bandIndex: 0, timeFrequencyChange: tf) }
        }
        for intensity in [Int.min, -1, 22, Int.max] {
            #expect(throws: CELTShapeCodingError.invalidIntensity) { try CELTShapeCoding(frameSampleCount: 120, bandIndex: 0, intensityBand: intensity) }
        }
        for rounding in [Int.min, -2, 2, Int.max] {
            #expect(throws: CELTShapeCodingError.invalidThetaRounding) { try CELTShapeCoding(frameSampleCount: 120, bandIndex: 0, thetaRounding: rounding) }
        }
    }

    /// Length, finiteness, norm, allocation, frame authority, folding, fill and amplitude
    /// checks preserve every observable entropy field; decoder performs equivalent checks.
    @Test func invalidInputsPreserveEntropy() throws {
        let q = try CELTShapeCoding(frameSampleCount: 120, bandIndex: 8)
        var encoder = try OpusRangeEncoder(frameByteCount: 16)
        var saved = encoder
        for values: [Float] in [[], [1], [1, 1], [.nan, 0], [.infinity, 0], [-.infinity, 0]] {
            #expect(throws: CELTShapeCodingError.invalidCoefficients) {
                try q.encode(values, allocationEighthBits: 0, remainingEighthBits: 100, into: &encoder)
            }
        }
        for pair in [(Int.min, 0), (-1, 0), (16_384, 16_384), (100, 0), (0, -1), (0, Int.max), (0, 1_017)] {
            #expect(throws: CELTShapeCodingError.invalidBudget) {
                try q.encode([1, 0], allocationEighthBits: pair.0, remainingEighthBits: pair.1, into: &encoder)
            }
            var decoder = try OpusRangeDecoder(frame: Data(repeating: 0, count: 16))
            let before = decoder
            #expect(throws: CELTShapeCodingError.invalidBudget) {
                try q.decode(allocationEighthBits: pair.0, remainingEighthBits: pair.1, from: &decoder)
            }
            #expect(decoder.finalRange == before.finalRange && decoder.bitsUsed == before.bitsUsed && decoder.fractionalBitsUsed == before.fractionalBitsUsed)
        }
        for low: [Float] in [[], [1], [33, 0], [.nan, 0], [.infinity, 0]] {
            #expect(throws: CELTShapeCodingError.invalidFolding) {
                try q.encode([1, 0], allocationEighthBits: 0, remainingEighthBits: 100, folding: low, into: &encoder)
            }
            var decoder = try OpusRangeDecoder(frame: Data(repeating: 0, count: 16))
            #expect(throws: CELTShapeCodingError.invalidFolding) {
                try q.decode(allocationEighthBits: 0, remainingEighthBits: 100, folding: low, from: &decoder)
            }
        }
        for energy: [Float] in [[], [1, 1], [-1], [.nan], [.infinity], [1_000_001]] {
            #expect(throws: CELTShapeCodingError.invalidEnergy) {
                try q.encode([1, 0], allocationEighthBits: 0, remainingEighthBits: 100, bandEnergies: energy, into: &encoder)
            }
        }
        #expect(throws: CELTShapeCodingError.invalidFillMask) {
            try q.encode([1, 0], allocationEighthBits: 0, remainingEighthBits: 100, fillMask: 2, into: &encoder)
        }
        var decoder = try OpusRangeDecoder(frame: Data(repeating: 0, count: 16))
        #expect(throws: CELTShapeCodingError.invalidFillMask) {
            try q.decode(allocationEighthBits: 0, remainingEighthBits: 100, fillMask: 2, from: &decoder)
        }
        #expect(encoder.finalRange == saved.finalRange && encoder.bitsUsed == saved.bitsUsed && encoder.fractionalBitsUsed == saved.fractionalBitsUsed)
        #expect(try encoder.finalize() == saved.finalize())
    }

    /// Zero entropy permits deterministic noise and explicit empty occupancy. Defaults
    /// select all blocks and unit energy; repeated equal seeds preserve exact reconstruction.
    @Test func zeroBudgetDefaultsAndSeedContinuation() throws {
        let q = try CELTShapeCoding(frameSampleCount: 960, bandIndex: 20, transient: true)
        var encoder = try OpusRangeEncoder(frameByteCount: 0)
        let empty = Array(repeating: Float(0), count: q.dimensions)
        let v = try q.encode(empty, allocationEighthBits: 0, remainingEighthBits: 0, seed: 42, into: &encoder)
        #expect(v.seed != 42 && v.collapseMask == 255)
        #expect(abs(v.coefficients.reduce(Float(0)) { $0 + $1 * $1 } - 1) < 0.00001)
        var decoder = try OpusRangeDecoder(frame: Data())
        let d = try q.decode(allocationEighthBits: 0, remainingEighthBits: 0, seed: 42, from: &decoder)
        #expect(v == d)
        var second = try OpusRangeDecoder(frame: Data())
        let missing = try q.decode(allocationEighthBits: 0, remainingEighthBits: 0, seed: 42, fillMask: 0, from: &second)
        #expect(missing.seed == 42 && missing.collapseMask == 0)
        #expect(missing.coefficients.allSatisfy { $0 == 0 })
    }

    /// Compares complete independently sized spectra rather than hiding truncated-array differences.
    /// - Parameters:
    ///   - actual: Owned scalar-float reconstruction.
    ///   - expected: Independent official scalar-float fixture, tolerance 3e-5 absolute.
    private func assertFloats(_ actual: [Float], _ expected: [Float]) {
        #expect(actual.count == expected.count)
        #expect(zip(actual, expected).allSatisfy { abs($0 - $1) <= 0.00003 })
    }
}
